style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://i.pinimg.com/736x/d6/20/c6/d620c6c99dd8a6724e21a063014a49f5.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ffffff !important; 
  }
  .container, .content, .section, .profile-header, .game-card, .card-item {
    background: rgba(0, 0, 0, 0.6) !important; 
    border-radius: 12px !important;
    padding: 10px !important;
  }
  a {
    color: #ff4d6d !important;
  }
  a:hover {
    color: #ff99aa !important; 
  }
  .btn-primary, .btn-secondary {
    background-color: #ff4d6d !important;
    border: none !important;
    color: white !important;
    border-radius: 8px !important;
  }
  .btn-primary:hover, .btn-secondary:hover {
    background-color: #ff1a40 !important;
  }
  h1, h2, h3, h4, h5 {
    color: #ff4d6d !important;
    text-shadow: 2px 2px 6px black !important;
  }
}
